export function InlineApprovalCard({ approvalId, initialApproval }: { approvalId: string; initialApproval?: Approval }) {
  const approvalQuery = useApproval(initialApproval ? null : approvalId);
  const approval = initialApproval ?? approvalQuery.data;
  const decideMutation = useDecideApproval();

  const handleDecision = (decision: 'approved' | 'rejected') => {
    decideMutation.mutate({
      approvalId,
      body: { decision },
      scope: `approval:decide:${approvalId}:${decision}`
    });
  };

  return (
    <div className="rounded-[18px] border border-[var(--border-approval)] bg-[var(--surface-approval)] p-4 shadow-sm" style={{ boxShadow: 'var(--specular-rim)' }}>
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <ShieldAlert size={16} className="text-amber-400" />
          <span className="text-[13px] font-semibold text-[var(--text)]">Action Approval Required</span>
        </div>
        <span className="rounded-full bg-amber-500/15 px-2 py-0.5 text-[11px] font-medium text-amber-300">
          {approval?.tool_name ?? 'tool_call'}
        </span>
      </div>
      {/* Arguments preview */}
      <pre className="mt-3 max-h-40 overflow-auto rounded-[10px] bg-[color-mix(in_srgb,var(--surface-solid)_90%,transparent)] p-2.5 font-mono text-[12px] text-[var(--text-muted)]">
        {JSON.stringify(approval?.arguments ?? {}, null, 2)}
      </pre>
      <div className="mt-4 flex items-center justify-end gap-2.5">
        <button
          type="button"
          onClick={() => handleDecision('rejected')}
          disabled={decideMutation.isPending}
          className="btn btn-ghost h-9 px-4 text-xs font-semibold"
        >
          <X size={14} /> Reject
        </button>
        <button
          type="button"
          onClick={() => handleDecision('approved')}
          disabled={decideMutation.isPending}
          className="btn btn-primary h-9 px-4 text-xs font-semibold"
        >
          <Check size={14} /> Approve & Continue
        </button>
      </div>
    </div>
  );
}
```

